-- 109 AI phase four ChangeSet planning, selection and recovery metadata; forward-only and idempotent.
SET @schema_name=DATABASE();
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_change_set' AND COLUMN_NAME='plan_digest'),'ALTER TABLE `fun_ai_change_set` ADD COLUMN `plan_digest` char(64) NOT NULL DEFAULT \'\' AFTER `base_digest`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
ALTER TABLE `fun_ai_change_set` MODIFY COLUMN `plan_digest` char(64) NOT NULL DEFAULT '';
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_change_set' AND COLUMN_NAME='selection'),'ALTER TABLE `fun_ai_change_set` ADD COLUMN `selection` json NULL AFTER `base_file_hashes`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
ALTER TABLE `fun_ai_change_set` MODIFY COLUMN `selection` json NULL;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_change_set' AND COLUMN_NAME='recovery_version'),'ALTER TABLE `fun_ai_change_set` ADD COLUMN `recovery_version` int unsigned NOT NULL DEFAULT 0 AFTER `recovery_status`','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
ALTER TABLE `fun_ai_change_set` MODIFY COLUMN `recovery_version` int unsigned NOT NULL DEFAULT 0;
SET @sql=IF(NOT EXISTS(SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_change_set' AND INDEX_NAME='idx_ai_change_set_owner_status'),'ALTER TABLE `fun_ai_change_set` ADD KEY `idx_ai_change_set_owner_status` (`created_by`,`conversation_id`,`status`,`id`)','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @ai_group_id=(SELECT `id` FROM `fun_permission` WHERE `source_type`='admin_web' AND `source_name`='ai_development' AND `resource_type`='group' ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `fun_permission` (`pid`,`app_name`,`code`,`obj`,`act`,`name`,`resource_type`,`status`,`is_public`,`source_type`,`source_name`,`created_at`,`updated_at`,`sort_order`,`deleted_at`) VALUES
(@ai_group_id,'console','console/development.ai:changesetapply','console/development.ai','changesetapply',CONVERT(X'E5BA94E794A8E58F98E69BB4E99B86' USING utf8mb4),'route',1,0,'admin_web','ai_development',NOW(),NOW(),51,NULL),
(@ai_group_id,'console','console/development.ai:changesetrecover','console/development.ai','changesetrecover',CONVERT(X'E681A2E5A496E58F98E69BB4E99B86' USING utf8mb4),'route',1,0,'admin_web','ai_development',NOW(),NOW(),52,NULL),
(@ai_group_id,'console','console/development.ai:crudproposalpreview','console/development.ai','crudproposalpreview',CONVERT(X'E9A284E8A78843525544E68F90E6A188' USING utf8mb4),'route',1,0,'admin_web','ai_development',NOW(),NOW(),53,NULL),
(@ai_group_id,'console','console/development.ai:crudproposalapply','console/development.ai','crudproposalapply',CONVERT(X'E5BA94E794A84352525544E68F90E6A188' USING utf8mb4),'route',1,0,'admin_web','ai_development',NOW(),NOW(),54,NULL);
UPDATE `fun_permission` SET `pid`=@ai_group_id,`app_name`='console',`obj`='console/development.ai',`act`=SUBSTRING_INDEX(`code`,':',-1),`resource_type`='route',`status`=1,`is_public`=0,`source_type`='admin_web',`source_name`='ai_development',`updated_at`=NOW(),`sort_order`=CASE `code` WHEN 'console/development.ai:changesetapply' THEN 51 WHEN 'console/development.ai:changesetrecover' THEN 52 WHEN 'console/development.ai:crudproposalpreview' THEN 53 WHEN 'console/development.ai:crudproposalapply' THEN 54 END,`deleted_at`=NULL WHERE `code` IN ('console/development.ai:changesetapply','console/development.ai:changesetrecover','console/development.ai:crudproposalpreview','console/development.ai:crudproposalapply');